import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0L
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) result else -result
    }
}

private data class Segment(val sum: Long, val minPrefix: Long)

private fun concatenate(a: Segment, b: Segment): Segment {
    return Segment(
        a.sum + b.sum,
        minOf(a.minPrefix, a.sum + b.minPrefix)
    )
}

private fun repeatSegment(segment: Segment, times: Long): Segment {
    var exponent = times
    var base = segment
    var result = Segment(0L, 0L)

    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = concatenate(result, base)
        }
        base = concatenate(base, base)
        exponent = exponent shr 1
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val m = fs.nextLong()

    val a = IntArray(n)
    val b = IntArray(n)
    val difference = IntArray(n)

    for (i in 0 until n) a[i] = fs.nextLong().toInt()

    var baseCost = 0L
    for (i in 0 until n) {
        b[i] = fs.nextLong().toInt()
        baseCost += b[i].toLong() * m
        difference[i] = a[i] - b[i]
    }

    val totalLength = n.toLong() * m
    val selections = totalLength / 2
    val remainingSlots = selections - 1
    val period = n / gcd(n, 2)

    var previousSelected = 0L
    var additionalCost = 0L

    for (cost in -9..9) {
        val firstArrival = if (difference[0] <= cost) 1L else 0L

        var periodSum = 0L
        var periodMinimum = 0L

        for (k in 1..period) {
            val firstIndex = (2 * k - 1) % n
            val secondIndex = (2 * k) % n
            val arrivals =
                (if (difference[firstIndex] <= cost) 1 else 0) +
                (if (difference[secondIndex] <= cost) 1 else 0)

            periodSum += arrivals - 1L
            periodMinimum = minOf(periodMinimum, periodSum)
        }

        val fullPeriods = remainingSlots / period
        val remainder = (remainingSlots % period).toInt()

        var aggregate = repeatSegment(
            Segment(periodSum, periodMinimum),
            fullPeriods
        )

        var remainderSum = 0L
        var remainderMinimum = 0L
        for (k in 1..remainder) {
            val firstIndex = (2 * k - 1) % n
            val secondIndex = (2 * k) % n
            val arrivals =
                (if (difference[firstIndex] <= cost) 1 else 0) +
                (if (difference[secondIndex] <= cost) 1 else 0)

            remainderSum += arrivals - 1L
            remainderMinimum = minOf(remainderMinimum, remainderSum)
        }

        aggregate = concatenate(
            aggregate,
            Segment(remainderSum, remainderMinimum)
        )

        val selectedAtMostCost =
            firstArrival + remainingSlots + aggregate.minPrefix
        val selectedExactlyCost = selectedAtMostCost - previousSelected

        additionalCost += selectedExactlyCost * cost.toLong()
        previousSelected = selectedAtMostCost
    }

    println(baseCost + additionalCost)
}

private fun gcd(a: Int, b: Int): Int {
    var x = a
    var y = b
    while (y != 0) {
        val remainder = x % y
        x = y
        y = remainder
    }
    return x
}

import java.io.BufferedInputStream

private const val INF = Long.MAX_VALUE / 4

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value * sign
    }
}

private fun multiply(a: LongArray, b: LongArray, size: Int): LongArray {
    val result = LongArray(size * size) { INF }

    for (i in 0 until size) {
        val rowI = i * size
        for (k in 0 until size) {
            val av = a[rowI + k]
            if (av >= INF) continue
            val rowK = k * size
            for (j in 0 until size) {
                val bv = b[rowK + j]
                if (bv >= INF) continue
                val value = av + bv
                if (value < result[rowI + j]) {
                    result[rowI + j] = value
                }
            }
        }
    }
    return result
}

private fun multiplyVector(vector: LongArray, matrix: LongArray, size: Int): LongArray {
    val result = LongArray(size) { INF }

    for (i in 0 until size) {
        val vv = vector[i]
        if (vv >= INF) continue
        val row = i * size
        for (j in 0 until size) {
            val mv = matrix[row + j]
            if (mv >= INF) continue
            val value = vv + mv
            if (value < result[j]) result[j] = value
        }
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val openCost = IntArray(n) { fs.nextInt() }
    val closeCost = IntArray(n) { fs.nextInt() }

    val maxBalance = 2 * n
    val size = maxBalance + 1
    val blockLength = 2 * n
    val transition = LongArray(size * size) { INF }

    for (start in 0..maxBalance) {
        var dp = LongArray(size) { INF }
        dp[start] = 0L

        for (position in 0 until blockLength) {
            val residue = position % n
            val next = LongArray(size) { INF }

            for (balance in 0..maxBalance) {
                val current = dp[balance]
                if (current >= INF) continue

                if (balance < maxBalance) {
                    val value = current + openCost[residue]
                    if (value < next[balance + 1]) {
                        next[balance + 1] = value
                    }
                }

                if (balance > 0) {
                    val value = current + closeCost[residue]
                    if (value < next[balance - 1]) {
                        next[balance - 1] = value
                    }
                }
            }
            dp = next
        }

        for (end in 0..maxBalance) {
            transition[start * size + end] = dp[end]
        }
    }

    var exponent = m.toLong() / 2L
    var matrix = transition
    var vector = LongArray(size) { INF }
    vector[0] = 0L

    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            vector = multiplyVector(vector, matrix, size)
        }
        exponent = exponent shr 1
        if (exponent > 0) {
            matrix = multiply(matrix, matrix, size)
        }
    }

    print(vector[0])
}

