private data class StateInfo(val cycle: Long, val cost: Long)

fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val m = fs.nextLong()

    val a = IntArray(n) { fs.nextLong().toInt() }
    val b = IntArray(n) { fs.nextLong().toInt() }

    val length = n.toLong() * m
    val openCount = length / 2

    var answer = m * b.sumOf { it.toLong() }

    val counts = LongArray(19)
    var selectedCost = (a[0] - b[0]).toLong()

    if (openCount > 1) {
        val period = if (n % 2 == 0) n / 2 else n
        val firstArrival = IntArray(period)
        val secondArrival = IntArray(period)
        val arrivals = LongArray(19)

        for (j in 0 until period) {
            val k = j + 1
            val r1 = (2L * k - 1).rem(n).toInt()
            val r2 = (2L * k).rem(n).toInt()
            firstArrival[j] = a[r1] - b[r1] + 9
            secondArrival[j] = a[r2] - b[r2] + 9
            arrivals[firstArrival[j]]++
            arrivals[secondArrival[j]]++
        }

        var cumulative = 0L
        var threshold = 0
        while (threshold < 19) {
            cumulative += arrivals[threshold]
            if (cumulative >= period.toLong()) break
            threshold++
        }
        val excess = cumulative - period

        val steps = openCount - 1
        val fullCycles = steps / period
        val remainder = (steps % period).toInt()

        fun extractMin(): Int {
            for (i in 0 until 19) {
                if (counts[i] > 0) {
                    counts[i]--
                    return i
                }
            }
            error("Empty queue")
        }

        fun stateKey(limit: Int): String {
            val sb = StringBuilder()
            for (i in 0..limit) {
                if (i > 0) sb.append(',')
                sb.append(counts[i])
            }
            return sb.toString()
        }

        val seen = HashMap<String, StateInfo>()
        var cycle = 0L

        while (cycle < fullCycles) {
            val relevantLimit = if (excess > 0) threshold - 1 else threshold
            val qualified = if (excess > 0) counts[threshold] >= period else true

            if (qualified) {
                val key = if (relevantLimit < 0) "" else stateKey(relevantLimit)
                val previous = seen[key]
                if (previous != null) {
                    val cyclePeriod = cycle - previous.cycle
                    if (cyclePeriod > 0) {
                        val repeatCost = selectedCost - previous.cost
                        val repetitions = (fullCycles - cycle) / cyclePeriod
                        if (repetitions > 0) {
                            selectedCost += repeatCost * repetitions
                            if (excess > 0) {
                                counts[threshold] += excess * cyclePeriod * repetitions
                            }
                            cycle += cyclePeriod * repetitions
                            seen.clear()
                            continue
                        }
                    }
                } else {
                    seen[key] = StateInfo(cycle, selectedCost)
                }
            }

            var usedAboveThreshold = false
            for (j in 0 until period) {
                counts[firstArrival[j]]++
                counts[secondArrival[j]]++
                val chosen = extractMin()
                if (chosen > threshold) usedAboveThreshold = true
                selectedCost += (chosen - 9).toLong()
            }

            cycle++
            if (usedAboveThreshold) seen.clear()
        }

        for (j in 0 until remainder) {
            counts[firstArrival[j]]++
            counts[secondArrival[j]]++
            selectedCost += (extractMin() - 9).toLong()
        }
    }

    answer += selectedCost
    print(answer)
}

