fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val m = fs.nextLong()

    val a = LongArray(n) { fs.nextLong() }
    val b = LongArray(n) { fs.nextLong() }
    val saving = LongArray(n) { a[it] - b[it] }
    val start = LongArray(n) { m }

    fun feasible(): Boolean {
        val points = LongArray(n + 2)
        points[0] = 0L
        points[1] = m
        for (i in 0 until n) points[i + 2] = start[i]
        points.sort()

        var balance = 0L
        var idx = 0

        while (idx < points.size - 1) {
            val left = points[idx]
            var nextIdx = idx + 1
            while (nextIdx < points.size && points[nextIdx] == left) nextIdx++
            if (nextIdx >= points.size) break

            val right = points[nextIdx]
            if (left < right && left < m) {
                var rowNet = 0L
                var prefix = 0L
                var minPrefix = 0L

                for (r in 0 until n) {
                    val step = if (left >= start[r]) -1L else 1L
                    prefix += step
                    if (prefix < minPrefix) minPrefix = prefix
                }
                rowNet = prefix

                val rows = right - left
                val lowest = if (rowNet >= 0L) {
                    balance + minPrefix
                } else {
                    balance + (rows - 1L) * rowNet + minPrefix
                }

                if (lowest < 0L) return false
                balance += rows * rowNet
            }
            idx = nextIdx
        }
        return true
    }

    val order = (0 until n).sortedWith(
        compareByDescending<Int> { saving[it] }.thenBy { it }
    )

    for (r in order) {
        var low = 0L
        var high = m
        while (low < high) {
            val mid = (low + high) ushr 1
            start[r] = mid
            if (feasible()) {
                high = mid
            } else {
                low = mid + 1L
            }
        }
        start[r] = low
    }

    var answer = 0L
    for (r in 0 until n) {
        val closed = m - start[r]
        val opened = m - closed
        answer += opened * a[r] + closed * b[r]
    }

    print(answer)
}

