fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val m = fs.nextLong()

    val a = IntArray(n)
    val b = IntArray(n)

    for (i in 0 until n) a[i] = fs.nextLong().toInt()

    var sumB = 0L
    for (i in 0 until n) {
        b[i] = fs.nextLong().toInt()
        sumB += b[i]
    }

    val delta = IntArray(n) { a[it] - b[it] }
    val period = if (n % 2 == 0) n / 2 else n
    val totalPairs = n.toLong() * m / 2
    val repetitions = totalPairs / period

    val counts = LongArray(19)
    val before = LongArray(19)
    val previousSelection = IntArray(period)
    val currentSelection = IntArray(period)
    var hasPrevious = false

    var selectedCost = 0L
    var cycle = 0L

    while (cycle < repetitions) {
        for (i in 0 until 19) before[i] = counts[i]

        var cycleCost = 0L

        for (k in 0 until period) {
            val evenResidue = (2 * k) % n
            val oddResidue = (2 * k + 1) % n

            counts[delta[evenResidue] + 9]++

            var chosen = 0
            while (counts[chosen] == 0L) chosen++
            counts[chosen]--
            currentSelection[k] = chosen
            cycleCost += chosen - 9L

            counts[delta[oddResidue] + 9]++
        }

        selectedCost += cycleCost

        var sameSelection = hasPrevious
        if (sameSelection) {
            for (i in 0 until period) {
                if (previousSelection[i] != currentSelection[i]) {
                    sameSelection = false
                    break
                }
            }
        }

        var nonDecreasing = true
        for (i in 0 until 19) {
            if (counts[i] < before[i]) {
                nonDecreasing = false
                break
            }
        }

        if (sameSelection && nonDecreasing) {
            val remaining = repetitions - cycle - 1
            selectedCost += cycleCost * remaining
            break
        }

        for (i in 0 until period) previousSelection[i] = currentSelection[i]
        hasPrevious = true
        cycle++
    }

    val answer = sumB * m + selectedCost
    print(answer)
}
